from datetime import datetime, timedelta
import sqlite3

import streamlit as st

import calendar_export
import config
import database
import gaps
import models
import ui_components


def _navigation(connection, now):
    """Render bounded Previous/Today/Next navigation and return the selected Monday."""
    first, last = gaps.navigation_bounds(*database.get_event_date_range(connection))
    today = gaps.week_start(now)
    monday = st.session_state.get('ww_week_start', today)
    if first is not None:
        monday = min(max(monday, first), last)
    st.session_state['ww_week_start'] = monday
    previous, current, following = st.columns(3)
    if previous.button('Previous week', disabled=first is None or monday <= first,
                       key='ww_previous_week'):
        st.session_state['ww_week_start'] = monday - timedelta(days=config.DAYS_PER_WEEK)
        st.rerun()
    if current.button('Today', disabled=first is None or not first <= today <= last,
                      key='ww_today'):
        st.session_state['ww_week_start'] = today
        st.rerun()
    if following.button('Next week', disabled=last is None or monday >= last,
                        key='ww_next_week'):
        st.session_state['ww_week_start'] = monday + timedelta(days=config.DAYS_PER_WEEK)
        st.rerun()
    return monday


def _confirmed_blocks(connection, start, end):
    """Read any existing local-user confirmations and their IDs, without adding confirmation UI."""
    frame = database.get_calendar_confirmations(connection, start, end)
    blocks, ids = [], set()
    for row in frame.reset_index().to_dict('records'):
        event = models.event_from_row(row)
        blocks.append(models.BusyBlock(event.start, event.end, event.title, True, event.event_id))
        ids.add(event.event_id)
    return blocks, ids


def _day_items(day, blocks, free_gaps, now):
    """Return clipped busy blocks and non-ended gaps in chronological display order."""
    start = datetime.combine(day, datetime.min.time())
    end = start + timedelta(days=1)
    items = []
    for block in blocks:
        if block.start < end and block.end > start:
            items.append((max(start, block.start), min(end, block.end), 'busy', block))
    for gap in free_gaps:
        if gap.day == day and gap.end > now:
            items.append((gap.start, gap.end, 'gap', gap))
    return sorted(items, key=lambda item: item[0])


def _draw_day(day, labels, blocks, free_gaps, hide_titles, now):
    """Render one day using built-in Streamlit containers and visible time labels."""
    st.markdown(f'**{day:%a}** {day:%d.%m.}')
    if day == now.date():
        st.badge('Today', color='blue')
    for label in labels.get(day, []):
        st.caption('All-day entry' if hide_titles else label)
    for start, end, kind, item in _day_items(day, blocks, free_gaps, now):
        with st.container(border=True):
            if kind == 'gap':
                st.caption(item.label())
            else:
                st.caption(f':gray[{start:%H:%M}–{end:%H:%M}]')
                st.text('Busy' if hide_titles and not item.is_weekwise else item.title or 'Busy')
                if item.is_weekwise:
                    st.caption('Confirmed')


def _data_panel(connection, start, end):
    """Retain M1 source diagnostics and provide the M2 team calendar-compatibility download."""
    with st.expander('Data sources and calendar export check'):
        st.dataframe(database.get_source_counts_df(connection), hide_index=True)
        st.dataframe(database.get_import_log_df(connection), hide_index=True)
        events = database.get_events_df(connection, start, end)
        if not events.empty:
            row = events.reset_index().iloc[0].to_dict()
            event = models.event_from_row(row)
            st.caption(f'Calendar compatibility check: {event}')
            st.download_button('Download test event (.ics)', calendar_export.build_ics(event),
                                file_name='weekwise-test.ics', mime='text/calendar',
                                key='ww_test_calendar_export')


def render_week(connection, now=None):
    """Render the seven-column M2 grid with calendar blocks, labels, free gaps and navigation."""
    now = config.local_now(now)
    monday = _navigation(connection, now)
    start = datetime.combine(monday, datetime.min.time())
    end = start + timedelta(days=config.DAYS_PER_WEEK)
    st.title(f'Week {monday.isocalendar().week} · {monday:%d.%m.} – '
             f'{(end - timedelta(days=1)):%d.%m.%Y}')
    ui_components.render_calendar_controls(connection, start, end)
    confirmed, known_ids = _confirmed_blocks(connection, start, end)
    result = ui_components.cached_calendar(
        st.session_state['ww_calendar_mode'], start, end,
        st.session_state['ww_calendar_link'], st.session_state['ww_calendar_upload'],
        st.session_state['ww_all_day_busy'], tuple(sorted(known_ids)),
        ui_components.calendar_file_revision())
    blocks, labels, recognized, used_mode, message = result
    ui_components.render_sidebar_status(used_mode)
    if message:
        st.warning(message)
    blocks = blocks + confirmed
    intervals = [(block.start, block.end) for block in blocks]
    free_gaps = gaps.find_gaps_for_week(monday, intervals) if used_mode != 'unavailable' else []
    if used_mode != 'unavailable' and not free_gaps:
        st.info('Your week is full – no free gaps of 60 minutes or more.')
    # Course: L04 – built-in columns and containers supply the grid, without HTML or CSS.
    for column, day in zip(st.columns(config.DAYS_PER_WEEK), gaps.week_days(monday)):
        with column:
            _draw_day(day, labels, blocks, free_gaps, st.session_state['ww_hide_busy_titles'], now)
    _data_panel(connection, start, end)


try:
    render_week(ui_components.cached_connection())
except (OSError, ValueError, KeyError, sqlite3.Error):
    st.error('Could not load your week. Please check your calendar input and try again.')
